@TestOn('vm')
library;

import 'package:drift/drift.dart';
import 'package:drift/native.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:photolib_data/src/replica.dart';
import 'package:test/test.dart';
import 'generated/schema.dart';

import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v2.dart' as v2;

// Generated by `dart run drift_dev make-migrations`, then kept to the tables a step changes; every schema's migration to
// the current one is checked in test/migration_test.dart.
void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  final verifier = SchemaVerifier(GeneratedHelper());

  test('v2 keeps every local asset, present and outside any folder', () async {
    final id = Uint8List(16)..[15] = 1;
    await verifier.testWithDataIntegrity(
      oldVersion: 1,
      newVersion: 2,
      createOld: v1.DatabaseAtV1.new,
      createNew: v2.DatabaseAtV2.new,
      openTestedDatabase: (e) =>
          Replica(e, openBackup: (_) => NativeDatabase.memory()),
      createItems: (batch, old) => batch.insert(
        old.localAsset,
        v1.LocalAssetCompanion.insert(
          id: id,
          source: 'mediastore',
          sourceId: '42',
          size: 7,
          mtime: 8,
        ),
      ),
      validateItems: (db) async =>
          expect(await db.select(db.localAsset).get(), [
            v2.LocalAssetData(
              id: id,
              source: 'mediastore',
              volume: '',
              sourceId: '42',
              size: 7,
              mtime: 8,
              state: 'present',
            ),
          ]),
    );
  });
}
